input.content:
export type DomainErrorCode =
  | "CART_NOT_FOUND"
  | "PRODUCT_NOT_FOUND"
  | "INSUFFICIENT_STOCK"
  | "COUPON_INVALID"
  | "CART_EMPTY"
  | "VERSION_CONFLICT";

export class DomainError extends Error {
  readonly code: DomainErrorCode;

  constructor(code: DomainErrorCode, message: string) {
    super(message);
    this.name = "DomainError";
    this.code = code;
  }
}

export class CartNotFoundError extends DomainError {
  constructor(cartId: string) {
    super("CART_NOT_FOUND", `Cart not found: ${cartId}`);
    this.name = "CartNotFoundError";
  }
}

export class ProductNotFoundError extends DomainError {
  constructor(productId: string) {
    super("PRODUCT_NOT_FOUND", `Product not found: ${productId}`);
    this.name = "ProductNotFoundError";
  }
}

export class InsufficientStockError extends DomainError {
  constructor(productId: string, requested: number, available: number) {
    super(
      "INSUFFICIENT_STOCK",
      `Insufficient stock for ${productId}: requested ${requested}, available ${available}`,
    );
    this.name = "InsufficientStockError";
  }
}

export class CouponInvalidError extends DomainError {
  constructor(code: string, reason: string) {
    super("COUPON_INVALID", `Coupon "${code}" is not valid: ${reason}`);
    this.name = "CouponInvalidError";
  }
}

export class CartEmptyError extends DomainError {
  constructor(cartId: string) {
    super("CART_EMPTY", `Cart is empty: ${cartId}`);
    this.name = "CartEmptyError";
  }
}

export class VersionConflictError extends DomainError {
  readonly currentVersion: number;

  constructor(cartId: string, expectedVersion: number, currentVersion: number) {
    super(
      "VERSION_CONFLICT",
      `Cart ${cartId} was modified concurrently (expected version ${expectedVersion}, current ${currentVersion})`,
    );
    this.name = "VersionConflictError";
    this.currentVersion = currentVersion;
  }
}

export type DomainEventType =
  | "cart.created"
  | "cart.item_added"
  | "cart.item_quantity_updated"
  | "cart.item_removed"
  | "cart.cleared"
  | "coupon.applied"
  | "coupon.removed"
  | "cart.checked_out";

export interface DomainEvent {
  type: DomainEventType;
  cartId: string;
  occurredAt: string;
  payload: Record<string, unknown>;
}

export function domainEvent(
  type: DomainEventType,
  cartId: string,
  payload: Record<string, unknown> = {},
): DomainEvent {
  return { type, cartId, occurredAt: new Date().toISOString(), payload };
}

export interface Product {
  id: string;
  name: string;
  priceCents: number;
  stock: number;
}

export type CouponType = "percentage" | "fixed";

export interface Coupon {
  code: string;
  type: CouponType;
  /** Percentage (0-100) for "percentage" coupons, cents for "fixed" coupons. */
  value: number;
  minSubtotalCents?: number;
  maxDiscountCents?: number;
  description?: string;
  /** ISO-8601 date; the coupon is invalid after this instant. */
  expiresAt?: string;
}

import { CartEmptyError, InsufficientStockError, ProductNotFoundError } from "./errors.js";
import type { Product } from "./catalog.js";

export interface CartItem {
  productId: string;
  name: string;
  unitPriceCents: number;
  quantity: number;
}

export interface CartProps {
  id: string;
  ownerId: string | null;
  items: CartItem[];
  couponCode: string | null;
  version: number;
  createdAt: string;
  updatedAt: string;
  expiresAt: string | null;
}

export const MAX_ITEM_QUANTITY = 99;

export class Cart {
  private props: CartProps;

  private constructor(props: CartProps) {
    this.props = props;
  }

  static create(id: string, ownerId: string | null, ttlMs: number | null): Cart {
    const now = new Date();
    return new Cart({
      id,
      ownerId,
      items: [],
      couponCode: null,
      version: 0,
      createdAt: now.toISOString(),
      updatedAt: now.toISOString(),
      expiresAt: ttlMs === null ? null : new Date(now.getTime() + ttlMs).toISOString(),
    });
  }

  static rehydrate(props: CartProps): Cart {
    return new Cart({
      ...props,
      items: props.items.map((item) => ({ ...item })),
    });
  }

  get id(): string {
    return this.props.id;
  }

  get ownerId(): string | null {
    return this.props.ownerId;
  }

  get items(): readonly CartItem[] {
    return this.props.items;
  }

  get couponCode(): string | null {
    return this.props.couponCode;
  }

  get version(): number {
    return this.props.version;
  }

  get createdAt(): string {
    return this.props.createdAt;
  }

  get updatedAt(): string {
    return this.props.updatedAt;
  }

  get expiresAt(): string | null {
    return this.props.expiresAt;
  }

  isEmpty(): boolean {
    return this.props.items.length === 0;
  }

  isExpired(now: Date = new Date()): boolean {
    return this.props.expiresAt !== null && new Date(this.props.expiresAt).getTime() <= now.getTime();
  }

  /** Adds a product, merging with the existing line if present. Validates against catalog stock. */
  addItem(product: Product, quantity: number): CartItem {
    if (quantity < 1 || quantity > MAX_ITEM_QUANTITY) {
      throw new RangeError(`Quantity must be between 1 and ${MAX_ITEM_QUANTITY}`);
    }
    const existing = this.props.items.find((item) => item.productId === product.id);
    const nextQuantity = (existing?.quantity ?? 0) + quantity;
    if (nextQuantity > MAX_ITEM_QUANTITY) {
      throw new RangeError(`Quantity must not exceed ${MAX_ITEM_QUANTITY} per line`);
    }
    if (nextQuantity > product.stock) {
      throw new InsufficientStockError(product.id, nextQuantity, product.stock);
    }
    if (existing) {
      existing.quantity = nextQuantity;
      existing.unitPriceCents = product.priceCents;
      existing.name = product.name;
      return { ...existing };
    }
    const item: CartItem = {
      productId: product.id,
      name: product.name,
      unitPriceCents: product.priceCents,
      quantity,
    };
    this.props.items.push(item);
    return { ...item };
  }

  /** Sets the absolute quantity of a line. Quantity 0 removes the line. */
  setItemQuantity(productId: string, quantity: number, availableStock: number): CartItem | null {
    if (quantity < 0 || quantity > MAX_ITEM_QUANTITY) {
      throw new RangeError(`Quantity must be between 0 and ${MAX_ITEM_QUANTITY}`);
    }
    const index = this.props.items.findIndex((item) => item.productId === productId);
    if (index === -1) {
      throw new ProductNotFoundError(productId);
    }
    if (quantity === 0) {
      this.props.items.splice(index, 1);
      return null;
    }
    if (quantity > availableStock) {
      throw new InsufficientStockError(productId, quantity, availableStock);
    }
    const item = this.props.items[index]!;
    item.quantity = quantity;
    return { ...item };
  }

  removeItem(productId: string): boolean {
    const index = this.props.items.findIndex((item) => item.productId === productId);
    if (index === -1) return false;
    this.props.items.splice(index, 1);
    return true;
  }

  clear(): void {
    this.props.items = [];
    this.props.couponCode = null;
  }

  applyCoupon(code: string): void {
    this.props.couponCode = code.trim().toUpperCase();
  }

  removeCoupon(): boolean {
    if (this.props.couponCode === null) return false;
    this.props.couponCode = null;
    return true;
  }

  ensureNotEmpty(): void {
    if (this.isEmpty()) {
      throw new CartEmptyError(this.props.id);
    }
  }

  /** Bumps the optimistic-concurrency version and the updatedAt timestamp. */
  touch(now: Date = new Date()): void {
    this.props.version += 1;
    this.props.updatedAt = now.toISOString();
  }

  toProps(): CartProps {
    return {
      ...this.props,
      items: this.props.items.map((item) => ({ ...item })),
    };
  }
}

import type { CartItem } from "./cart.js";
import type { Coupon } from "./catalog.js";
import { CouponInvalidError } from "./errors.js";

export interface PricingConfig {
  /** VAT/sales-tax rate, e.g. 0.21 for 21%. */
  taxRate: number;
  shippingFlatCents: number;
  /** Subtotal (after discount) at or above which shipping is free. */
  freeShippingThresholdCents: number;
  currency: string;
}

export const DEFAULT_PRICING_CONFIG: PricingConfig = {
  taxRate: 0.21,
  shippingFlatCents: 499,
  freeShippingThresholdCents: 10000,
  currency: "EUR",
};

export interface Totals {
  currency: string;
  subtotalCents: number;
  discountCents: number;
  taxCents: number;
  shippingCents: number;
  totalCents: number;
}

export function assertCouponUsable(coupon: Coupon, subtotalCents: number, now: Date = new Date()): void {
  if (coupon.expiresAt !== undefined && new Date(coupon.expiresAt).getTime() <= now.getTime()) {
    throw new CouponInvalidError(coupon.code, "expired");
  }
  if (coupon.minSubtotalCents !== undefined && subtotalCents < coupon.minSubtotalCents) {
    throw new CouponInvalidError(
      coupon.code,
      `requires a subtotal of at least ${coupon.minSubtotalCents} cents`,
    );
  }
}

export function computeDiscountCents(coupon: Coupon, subtotalCents: number): number {
  let discount =
    coupon.type === "percentage"
      ? Math.round((subtotalCents * coupon.value) / 100)
      : Math.min(coupon.value, subtotalCents);
  if (coupon.maxDiscountCents !== undefined) {
    discount = Math.min(discount, coupon.maxDiscountCents);
  }
  return Math.max(0, Math.min(discount, subtotalCents));
}

export function computeTotals(
  items: readonly CartItem[],
  coupon: Coupon | null,
  config: PricingConfig,
  now: Date = new Date(),
): Totals {
  const subtotalCents = items.reduce((sum, item) => sum + item.unitPriceCents * item.quantity, 0);

  let discountCents = 0;
  if (coupon !== null && subtotalCents > 0) {
    assertCouponUsable(coupon, subtotalCents, now);
    discountCents = computeDiscountCents(coupon, subtotalCents);
  }

  const discountedBase = subtotalCents - discountCents;
  const taxCents = Math.round(discountedBase * config.taxRate);
  const shippingCents =
    items.length === 0 || discountedBase >= config.freeShippingThresholdCents
      ? 0
      : config.shippingFlatCents;

  return {
    currency: config.currency,
    subtotalCents,
    discountCents,
    taxCents,
    shippingCents,
    totalCents: discountedBase + taxCents + shippingCents,
  };
}

import type { Cart } from "../domain/cart.js";
import type { Coupon, Product } from "../domain/catalog.js";
import type { DomainEvent } from "../domain/events.js";

export interface CartRepository {
  /** Inserts a new cart. Must fail with VersionConflictError if the id already exists. */
  insert(cart: Cart): Promise<void>;
  /**
   * Persists a cart using optimistic concurrency: succeeds only when the stored
   * version equals `expectedVersion`; otherwise throws VersionConflictError.
   */
  save(cart: Cart, expectedVersion: number): Promise<void>;
  /** Returns the cart, or null when it does not exist or has expired. */
  getById(cartId: string): Promise<Cart | null>;
}

export interface ProductCatalog {
  getById(productId: string): Promise<Product | null>;
  list(): Promise<Product[]>;
  /** Atomically decrements stock. Throws InsufficientStockError when not possible. */
  decrementStock(productId: string, quantity: number): Promise<void>;
}

export interface CouponRepository {
  getByCode(code: string): Promise<Coupon | null>;
}

export interface EventBus {
  publish(events: DomainEvent[]): Promise<void>;
}

import type { Cart } from "../domain/cart.js";
import type { Totals } from "../domain/pricing.js";

export interface CartView {
  id: string;
  ownerId: string | null;
  items: Array<{
    productId: string;
    name: string;
    unitPriceCents: number;
    quantity: number;
    lineTotalCents: number;
  }>;
  couponCode: string | null;
  totals: Totals;
  version: number;
  createdAt: string;
  updatedAt: string;
  expiresAt: string | null;
}

export function toCartView(cart: Cart, totals: Totals): CartView {
  return {
    id: cart.id,
    ownerId: cart.ownerId,
    items: cart.items.map((item) => ({
      ...item,
      lineTotalCents: item.unitPriceCents * item.quantity,
    })),
    couponCode: cart.couponCode,
    totals,
    version: cart.version,
    createdAt: cart.createdAt,
    updatedAt: cart.updatedAt,
    expiresAt: cart.expiresAt,
  };
}

import { randomUUID } from "node:crypto";
import { Cart } from "../domain/cart.js";
import type { DomainEvent } from "../domain/events.js";
import { domainEvent } from "../domain/events.js";
import {
  CartNotFoundError,
  CouponInvalidError,
  ProductNotFoundError,
  VersionConflictError,
} from "../domain/errors.js";
import { computeTotals, assertCouponUsable, type PricingConfig, type Totals } from "../domain/pricing.js";
import type { CartView } from "./cartView.js";
import { toCartView } from "./cartView.js";
import type { CartRepository, CouponRepository, EventBus, ProductCatalog } from "./ports.js";

export interface OrderSummary {
  orderId: string;
  cartId: string;
  items: CartView["items"];
  totals: Totals;
  checkedOutAt: string;
}

export interface CartServiceOptions {
  pricing: PricingConfig;
  /** Time-to-live applied to newly created carts. Null disables expiry. */
  cartTtlMs: number | null;
}

export class CartService {
  constructor(
    private readonly carts: CartRepository,
    private readonly catalog: ProductCatalog,
    private readonly coupons: CouponRepository,
    private readonly events: EventBus,
    private readonly options: CartServiceOptions,
  ) {}

  async createCart(ownerId: string | null = null): Promise<CartView> {
    const cart = Cart.create(randomUUID(), ownerId, this.options.cartTtlMs);
    await this.carts.insert(cart);
    await this.publish([domainEvent("cart.created", cart.id, { ownerId })]);
    return this.view(cart);
  }

  async getCart(cartId: string): Promise<CartView> {
    return this.view(await this.load(cartId));
  }

  async addItem(
    cartId: string,
    productId: string,
    quantity: number,
    expectedVersion?: number,
  ): Promise<CartView> {
    const cart = await this.loadForMutation(cartId, expectedVersion);
    const product = await this.catalog.getById(productId);
    if (!product) throw new ProductNotFoundError(productId);

    cart.addItem(product, quantity);
    await this.saveMutation(cart, [
      domainEvent("cart.item_added", cart.id, { productId, quantity }),
    ]);
    return this.view(cart);
  }

  async setItemQuantity(
    cartId: string,
    productId: string,
    quantity: number,
    expectedVersion?: number,
  ): Promise<CartView> {
    const cart = await this.loadForMutation(cartId, expectedVersion);

    if (quantity === 0) {
      cart.removeItem(productId);
      await this.saveMutation(cart, [
        domainEvent("cart.item_removed", cart.id, { productId }),
      ]);
      return this.view(cart);
    }

    const product = await this.catalog.getById(productId);
    if (!product) throw new ProductNotFoundError(productId);

    cart.setItemQuantity(productId, quantity, product.stock);
    await this.saveMutation(cart, [
      domainEvent("cart.item_quantity_updated", cart.id, { productId, quantity }),
    ]);
    return this.view(cart);
  }

  async removeItem(cartId: string, productId: string, expectedVersion?: number): Promise<CartView> {
    const cart = await this.loadForMutation(cartId, expectedVersion);
    const removed = cart.removeItem(productId);
    if (removed) {
      await this.saveMutation(cart, [
        domainEvent("cart.item_removed", cart.id, { productId }),
      ]);
    }
    return this.view(cart);
  }

  async applyCoupon(cartId: string, code: string, expectedVersion?: number): Promise<CartView> {
    const cart = await this.loadForMutation(cartId, expectedVersion);
    const normalized = code.trim().toUpperCase();
    const coupon = await this.coupons.getByCode(normalized);
    if (!coupon) {
      throw new CouponInvalidError(normalized, "unknown code");
    }
    const subtotal = cart.items.reduce((sum, item) => sum + item.unitPriceCents * item.quantity, 0);
    assertCouponUsable(coupon, subtotal);

    cart.applyCoupon(normalized);
    await this.saveMutation(cart, [domainEvent("coupon.applied", cart.id, { code: normalized })]);
    return this.view(cart);
  }

  async removeCoupon(cartId: string, expectedVersion?: number): Promise<CartView> {
    const cart = await this.loadForMutation(cartId, expectedVersion);
    const removed = cart.removeCoupon();
    if (removed) {
      await this.saveMutation(cart, [domainEvent("coupon.removed", cart.id, {})]);
    }
    return this.view(cart);
  }

  async clearCart(cartId: string, expectedVersion?: number): Promise<CartView> {
    const cart = await this.loadForMutation(cartId, expectedVersion);
    if (cart.isEmpty() && cart.couponCode === null) {
      return this.view(cart);
    }
    cart.clear();
    await this.saveMutation(cart, [domainEvent("cart.cleared", cart.id, {})]);
    return this.view(cart);
  }

  async checkout(cartId: string, expectedVersion?: number): Promise<OrderSummary> {
    const cart = await this.loadForMutation(cartId, expectedVersion);
    cart.ensureNotEmpty();

    // Re-validate every line against the current catalog before committing.
    for (const item of cart.items) {
      const product = await this.catalog.getById(item.productId);
      if (!product) throw new ProductNotFoundError(item.productId);
      if (product.stock < item.quantity) {
        const { InsufficientStockError } = await import("../domain/errors.js");
        throw new InsufficientStockError(item.productId, item.quantity, product.stock);
      }
    }

    const coupon = cart.couponCode ? await this.coupons.getByCode(cart.couponCode) : null;
    if (cart.couponCode && !coupon) {
      throw new CouponInvalidError(cart.couponCode, "no longer available");
    }
    const totals = computeTotals(cart.items, coupon ?? null, this.options.pricing);

    for (const item of cart.items) {
      await this.catalog.decrementStock(item.productId, item.quantity);
    }

    const orderId = randomUUID();
    const checkedOutAt = new Date().toISOString();
    const summary: OrderSummary = {
      orderId,
      cartId: cart.id,
      items: cart.items.map((item) => ({
        ...item,
        lineTotalCents: item.unitPriceCents * item.quantity,
      })),
      totals,
      checkedOutAt,
    };

    cart.clear();
    await this.saveMutation(cart, [
      domainEvent("cart.checked_out", cart.id, { orderId, totalCents: totals.totalCents }),
    ]);
    return summary;
  }

  private async load(cartId: string): Promise<Cart> {
    const cart = await this.carts.getById(cartId);
    if (!cart) throw new CartNotFoundError(cartId);
    return cart;
  }

  private async loadForMutation(cartId: string, expectedVersion?: number): Promise<Cart> {
    const cart = await this.load(cartId);
    if (expectedVersion !== undefined && expectedVersion !== cart.version) {
      throw new VersionConflictError(cartId, expectedVersion, cart.version);
    }
    return cart;
  }

  private async saveMutation(cart: Cart, events: DomainEvent[]): Promise<void> {
    const expectedVersion = cart.version;
    cart.touch();
    await this.carts.save(cart, expectedVersion);
    await this.publish(events);
  }

  private async view(cart: Cart): Promise<CartView> {
    const coupon = cart.couponCode ? await this.coupons.getByCode(cart.couponCode) : null;
    let totals: Totals;
    try {
      totals = computeTotals(cart.items, coupon ?? null, this.options.pricing);
    } catch {
      // A coupon that became invalid stays on the cart but contributes no discount.
      totals = computeTotals(cart.items, null, this.options.pricing);
    }
    return toCartView(cart, totals);
  }

  private async publish(events: DomainEvent[]): Promise<void> {
    try {
      await this.events.publish(events);
    } catch (error) {
      // Events are published after commit; a bus failure must not corrupt the write.
      // In production, replace with a transactional outbox.
      console.error("Failed to publish domain events", error);
    }
  }
}

