import { Cart } from "../domain/cart.js";
import { VersionConflictError } from "../domain/errors.js";
import type { CartRepository } from "../application/ports.js";

/**
 * Process-local cart store. Persists deep copies so callers cannot mutate
 * stored state by reference. Suitable for a single instance; swap for a
 * Redis/Postgres implementation of CartRepository to scale horizontally.
 */
export class InMemoryCartRepository implements CartRepository {
  private readonly store = new Map<string, ReturnType<Cart["toProps"]>>();

  async insert(cart: Cart): Promise<void> {
    if (this.store.has(cart.id)) {
      throw new VersionConflictError(cart.id, -1, cart.version);
    }
    this.store.set(cart.id, cart.toProps());
  }

  async save(cart: Cart, expectedVersion: number): Promise<void> {
    const stored = this.fresh(cart.id);
    const currentVersion = stored?.version ?? 0;
    if (currentVersion !== expectedVersion) {
      throw new VersionConflictError(cart.id, expectedVersion, currentVersion);
    }
    this.store.set(cart.id, cart.toProps());
  }

  async getById(cartId: string): Promise<Cart | null> {
    const props = this.fresh(cartId);
    return props ? Cart.rehydrate(props) : null;
  }

  /** Returns props if present and not expired; otherwise removes and returns null. */
  private fresh(cartId: string): ReturnType<Cart["toProps"]> | null {
    const props = this.store.get(cartId);
    if (!props) return null;
    if (props.expiresAt !== null && new Date(props.expiresAt).getTime() <= Date.now()) {
      this.store.delete(cartId);
      return null;
    }
    return structuredClone(props);
  }
}

import { InsufficientStockError, ProductNotFoundError } from "../domain/errors.js";
import type { Product } from "../domain/catalog.js";
import type { ProductCatalog } from "../application/ports.js";

export class InMemoryProductCatalog implements ProductCatalog {
  private readonly products = new Map<string, Product>();

  constructor(seed: Product[] = []) {
    for (const product of seed) {
      this.products.set(product.id, { ...product });
    }
  }

  async getById(productId: string): Promise<Product | null> {
    const product = this.products.get(productId);
    return product ? { ...product } : null;
  }

  async list(): Promise<Product[]> {
    return [...this.products.values()].map((product) => ({ ...product }));
  }

  /** All-or-nothing stock decrement: validates first, then mutates. */
  async decrementStock(productId: string, quantity: number): Promise<void> {
    const product = this.products.get(productId);
    if (!product) throw new ProductNotFoundError(productId);
    if (product.stock < quantity) {
      throw new InsufficientStockError(productId, quantity, product.stock);
    }
    product.stock -= quantity;
  }
}

export const SEED_PRODUCTS: Product[] = [
  { id: "kb-mech-01", name: "Teclado mecánico", priceCents: 8999, stock: 50 },
  { id: "mouse-wireless-01", name: "Ratón inalámbrico", priceCents: 2999, stock: 100 },
  { id: "monitor-27-4k", name: "Monitor 27\" 4K", priceCents: 21999, stock: 30 },
  { id: "usb-c-hub-7", name: "Hub USB-C 7 puertos", priceCents: 4599, stock: 80 },
  { id: "anc-headphones", name: "Auriculares ANC", priceCents: 12999, stock: 40 },
];

import type { Coupon } from "../domain/catalog.js";
import type { CouponRepository } from "../application/ports.js";

export class InMemoryCouponRepository implements CouponRepository {
  private readonly coupons = new Map<string, Coupon>();

  constructor(seed: Coupon[] = []) {
    for (const coupon of seed) {
      this.coupons.set(coupon.code.toUpperCase(), { ...coupon });
    }
  }

  async getByCode(code: string): Promise<Coupon | null> {
    const coupon = this.coupons.get(code.trim().toUpperCase());
    return coupon ? { ...coupon } : null;
  }
}

export const SEED_COUPONS: Coupon[] = [
  {
    code: "WELCOME10",
    type: "percentage",
    value: 10,
    description: "10% de descuento en todo el pedido",
  },
  {
    code: "TECH50",
    type: "fixed",
    value: 5000,
    minSubtotalCents: 20000,
    description: "50€ de descuento en pedidos de más de 200€",
  },
  {
    code: "SAVE5",
    type: "fixed",
    value: 500,
    maxDiscountCents: 500,
    description: "5€ de descuento",
  },
];

import type { DomainEvent } from "../domain/events.js";
import type { EventBus } from "../application/ports.js";

/**
 * Simple in-memory bus: keeps the published events (useful for tests and
 * local debugging) and optionally logs them. Swap for Kafka/RabbitMQ/SQS
 * or a transactional outbox when running multiple instances.
 */
export class InMemoryEventBus implements EventBus {
  readonly published: DomainEvent[] = [];

  constructor(private readonly logger?: (event: DomainEvent) => void) {}

  async publish(events: DomainEvent[]): Promise<void> {
    for (const event of events) {
      this.published.push(event);
      this.logger?.(event);
    }
  }
}

import { DEFAULT_PRICING_CONFIG, type PricingConfig } from "./domain/pricing.js";

export interface AppConfig {
  port: number;
  host: string;
  pricing: PricingConfig;
  cartTtlMs: number | null;
}

function numFromEnv(name: string, fallback: number): number {
  const raw = process.env[name];
  if (raw === undefined || raw === "") return fallback;
  const parsed = Number(raw);
  return Number.isFinite(parsed) ? parsed : fallback;
}

export function loadConfig(env: NodeJS.ProcessEnv = process.env): AppConfig {
  const ttlDays = numFromEnv("CART_TTL_DAYS", 7);
  return {
    port: numFromEnv("PORT", 3000),
    host: env.HOST ?? "0.0.0.0",
    cartTtlMs: ttlDays > 0 ? ttlDays * 24 * 60 * 60 * 1000 : null,
    pricing: {
      taxRate: numFromEnv("TAX_RATE", DEFAULT_PRICING_CONFIG.taxRate),
      shippingFlatCents: numFromEnv("SHIPPING_FLAT_CENTS", DEFAULT_PRICING_CONFIG.shippingFlatCents),
      freeShippingThresholdCents: numFromEnv(
        "FREE_SHIPPING_THRESHOLD_CENTS",
        DEFAULT_PRICING_CONFIG.freeShippingThresholdCents,
      ),
      currency: env.CURRENCY ?? DEFAULT_PRICING_CONFIG.currency,
    },
  };
}

import { z } from "zod";

export const createCartSchema = z.object({
  ownerId: z.string().min(1).max(128).nullish(),
});

export const addItemSchema = z.object({
  productId: z.string().min(1).max(128),
  quantity: z.number().int().min(1).max(99),
  expectedVersion: z.number().int().min(0).optional(),
});

export const updateItemSchema = z.object({
  quantity: z.number().int().min(0).max(99),
  expectedVersion: z.number().int().min(0).optional(),
});

export const applyCouponSchema = z.object({
  code: z.string().min(1).max(64),
  expectedVersion: z.number().int().min(0).optional(),
});

export const expectedVersionQuerySchema = z.object({
  expectedVersion: z.coerce.number().int().min(0).optional(),
});

export const cartIdParamsSchema = z.object({
  cartId: z.string().min(1).max(128),
});

export const cartItemParamsSchema = cartIdParamsSchema.extend({
  productId: z.string().min(1).max(128),
});

import Fastify, { type FastifyInstance, type FastifyRequest } from "fastify";
import { ZodError } from "zod";
import type { CartService } from "../application/cartService.js";
import type { ProductCatalog } from "../application/ports.js";
import {
  CartEmptyError,
  CartNotFoundError,
  CouponInvalidError,
  DomainError,
  InsufficientStockError,
  ProductNotFoundError,
  VersionConflictError,
} from "../domain/errors.js";
import {
  addItemSchema,
  applyCouponSchema,
  cartIdParamsSchema,
  cartItemParamsSchema,
  createCartSchema,
  expectedVersionQuerySchema,
  updateItemSchema,
} from "./schemas.js";

export interface AppDependencies {
  cartService: CartService;
  productCatalog: ProductCatalog;
}

function expectedVersionFrom(request: FastifyRequest): number | undefined {
  const header = request.headers["x-cart-version"];
  if (typeof header === "string" && /^\d+$/.test(header)) {
    return Number.parseInt(header, 10);
  }
  const body = request.body as { expectedVersion?: unknown } | undefined;
  if (typeof body?.expectedVersion === "number") {
    return body.expectedVersion;
  }
  const query = expectedVersionQuerySchema.safeParse(request.query);
  if (query.success && query.data.expectedVersion !== undefined) {
    return query.data.expectedVersion;
  }
  return undefined;
}

export function buildApp(deps: AppDependencies): FastifyInstance {
  const app = Fastify({ logger: false });
  const { cartService, productCatalog } = deps;

  app.setErrorHandler((error, _request, reply) => {
    if (error instanceof ZodError) {
      return reply.status(400).send({
        error: { code: "VALIDATION_ERROR", message: "Invalid request", details: error.issues },
      });
    }
    if (error instanceof DomainError) {
      const status =
        error instanceof CartNotFoundError || error instanceof ProductNotFoundError
          ? 404
          : error instanceof VersionConflictError || error instanceof InsufficientStockError
            ? 409
            : 400;
      const body: Record<string, unknown> = { error: { code: error.code, message: error.message } };
      if (error instanceof VersionConflictError) {
        body.error = { code: error.code, message: error.message, currentVersion: error.currentVersion };
      }
      return reply.status(status).send(body);
    }
    if (error instanceof RangeError) {
      return reply.status(400).send({ error: { code: "VALIDATION_ERROR", message: error.message } });
    }
    app.log.error(error);
    return reply.status(500).send({ error: { code: "INTERNAL_ERROR", message: "Unexpected error" } });
  });

  app.get("/health", async () => ({ status: "ok" }));

  app.get("/api/v1/products", async () => ({ data: await productCatalog.list() }));

  app.post("/api/v1/carts", async (request, reply) => {
    const body = createCartSchema.parse(request.body ?? {});
    const cart = await cartService.createCart(body.ownerId ?? null);
    return reply.status(201).send({ data: cart });
  });

  app.get("/api/v1/carts/:cartId", async (request) => {
    const { cartId } = cartIdParamsSchema.parse(request.params);
    return { data: await cartService.getCart(cartId) };
  });

  app.post("/api/v1/carts/:cartId/items", async (request) => {
    const { cartId } = cartIdParamsSchema.parse(request.params);
    const body = addItemSchema.parse(request.body);
    const cart = await cartService.addItem(
      cartId,
      body.productId,
      body.quantity,
